# Creates an immutable candidate with a temporary Git index.  The real index is
# touched only after a guarded ref advance, and then only for authorized paths.
[CmdletBinding()]
param(
	[Parameter(Mandatory)][ValidateSet('session-landing', 'primary-commit')][string] $Route,
	[Parameter(Mandatory)][string] $CurrentWorktree,
	[Parameter(Mandatory)][string] $PrimaryWorktree,
	[Parameter(Mandatory)][string] $CurrentBranch,
	[Parameter(Mandatory)][string] $PrimaryBranch,
	[Parameter(Mandatory)][string] $Baseline,
	[Parameter(Mandatory)][string] $ExpectedCurrentTip,
	[Parameter(Mandatory)][string] $ExpectedPrimaryTip,
	[Parameter(Mandatory)][string[]] $OwnedPaths,
	[Parameter(Mandatory)][string] $CommitMessageFile,
	[string] $VerifiedCandidateCommit,
	[string] $VerifiedCandidateTree,
	[string] $HistoryContractDigest,
	[string] $HistoryContractGeneratorDigest,
	[string] $HistoryContractCaptureDigest,
	[string] $HistoryContractRuntimeDigest,
	[string] $HistoryContractPatchDigest,
	[string] $HistoryContractMode,
	[string] $WorktreeCliExecutable,
	[string] $SessionLabel,
	[string] $OwnerToken,
	[switch] $AdvancePrimary,
	# Approval review receipt artifact ('broken-engine-finalize-approval-review/v1') proving the SmartGit
	# review was attempted for this exact candidate; mandatory on the -AdvancePrimary primary-commit route.
	[string] $ApprovalReviewResultFile,
	[ValidateSet('none', 'tree-mismatch', 'expected-tip-mismatch', 'postcondition', 'post-index-mutation', 'history-contract', 'history-generate', 'post-update-ref')][string] $FixtureFailure = 'none'
)
$ErrorActionPreference = 'Stop'; Set-StrictMode -Version Latest
$commonModule = Join-Path $PSScriptRoot '..\..\..\scripts\FinalizeWorkflowCommon.psm1'
if (-not (Test-Path -LiteralPath $commonModule)) { $commonModule = Join-Path $PSScriptRoot '..\..\..\..\.agents\scripts\FinalizeWorkflowCommon.psm1' }
Import-Module $commonModule -Force -DisableNameChecking
# Every commit-ID gate here anchors with \z rather than $: .NET's $ also matches before a trailing newline, so a hex value carrying one would pass and be echoed back as an identity.
$result = [ordered]@{ schemaVersion='broken-engine-finalize-candidate/v3';status='error';code='internal.error';message='Candidate transaction did not complete.';route=$Route;baseline=$(if($Baseline-cmatch'^[0-9a-f]{40}\z'){$Baseline}else{$null});tips=[ordered]@{current=$null;primary=$null;expectedCurrent=$(if($ExpectedCurrentTip-cmatch'^[0-9a-f]{40}\z'){$ExpectedCurrentTip}else{$null});expectedPrimary=$(if($ExpectedPrimaryTip-cmatch'^[0-9a-f]{40}\z'){$ExpectedPrimaryTip}else{$null})};candidate=[ordered]@{commit=$null;tree=$null;parent=$null;singleParent=$false;reconciled=$false};historyContract=$null;historyUpdate=[ordered]@{status='not-run';receipt=$null;rowDate=$null;jsonl=$null;svg=$null};final=[ordered]@{commit=$null;tree=$null;parent=$null;replacement=$false};ownedPaths=@();state=[ordered]@{before=$null;after=$null;unrelatedPreserved=$false;realIndexUntouched=$null};primaryAdvance=[ordered]@{attempted=$false;advanced=$false;rollback='not-required'} }
function Complete([int]$Exit,[string]$Status,[string]$Code,[string]$Message){$result.status=$Status;$result.code=$Code;$result.message=$Message;Write-Output ($result|ConvertTo-Json -Depth 16 -Compress);exit $Exit}
function Stop-Candidate([int]$Exit,[string]$Code,[string]$Message){$e=[InvalidOperationException]::new($Message);$e.Data['exit']=$Exit;$e.Data['code']=$Code;throw $e}
function Invoke-Native([string]$Root,[string]$Exe,[string[]]$Arguments,[hashtable]$Environment=@{}){$p=[Diagnostics.ProcessStartInfo]::new();$p.FileName=$Exe;$p.WorkingDirectory=$Root;$p.UseShellExecute=$false;$p.CreateNoWindow=$true;$p.RedirectStandardOutput=$true;$p.RedirectStandardError=$true;foreach($a in $Arguments){[void]$p.ArgumentList.Add($a)};foreach($k in $Environment.Keys){$p.Environment[$k]=$Environment[$k]};$x=[Diagnostics.Process]::new();$x.StartInfo=$p;if(-not$x.Start()){throw "Could not start '$Exe'."};$o=$x.StandardOutput.ReadToEndAsync();$e=$x.StandardError.ReadToEndAsync();$x.WaitForExit();$r=[pscustomobject]@{ExitCode=$x.ExitCode;Stdout=$o.GetAwaiter().GetResult();Stderr=$e.GetAwaiter().GetResult()};$x.Dispose();return $r}
# The stdin parameter must not be named $Input: PowerShell's automatic $input enumerator overwrites a same-named parameter, silently sending empty stdin.
function Invoke-NativeInput([string]$Root,[string]$Exe,[string[]]$Arguments,[string]$InputText){$p=[Diagnostics.ProcessStartInfo]::new();$p.FileName=$Exe;$p.WorkingDirectory=$Root;$p.UseShellExecute=$false;$p.CreateNoWindow=$true;$p.RedirectStandardOutput=$true;$p.RedirectStandardError=$true;$p.RedirectStandardInput=$true;foreach($a in $Arguments){[void]$p.ArgumentList.Add($a)};$x=[Diagnostics.Process]::new();$x.StartInfo=$p;if(-not$x.Start()){throw "Could not start '$Exe'."};$x.StandardInput.Write($InputText);$x.StandardInput.Close();$o=$x.StandardOutput.ReadToEndAsync();$e=$x.StandardError.ReadToEndAsync();$x.WaitForExit();$r=[pscustomobject]@{ExitCode=$x.ExitCode;Stdout=$o.GetAwaiter().GetResult();Stderr=$e.GetAwaiter().GetResult()};$x.Dispose();return $r}
function Invoke-Git([string]$Root,[string[]]$Arguments,[hashtable]$Environment=@{}){$r=Invoke-Native $Root 'git.exe' (@('-C',$Root)+$Arguments) $Environment;if($r.ExitCode-ne 0){throw "git $($Arguments -join ' ') failed: $($r.Stderr.Trim())"};return $r.Stdout}
function Test-Git([string]$Root,[string[]]$Arguments){return (Invoke-Native $Root 'git.exe' (@('-C',$Root)+$Arguments)).ExitCode-eq 0}
function Normalize-Path([string]$Path){$p=$Path.Replace('\','/');if([string]::IsNullOrWhiteSpace($p)-or[IO.Path]::IsPathRooted($p)-or$p -eq '.'-or$p -eq '..'-or$p.StartsWith('../')-or$p.Contains('/../')-or$p.EndsWith('/..')-or$p.StartsWith('./')-or$p.Contains('/./')-or$p.EndsWith('/.')-or$p.Contains('//')-or$p.Contains([char]0)-or$p -match '[*?:]'){Stop-Candidate 1 'input.path-invalid' "Invalid literal repository-relative path '$Path'."};return $p}
function Get-LiteralPathspec([string]$Path){return ":(literal)$Path"}
function Get-Status([string]$Root){return Invoke-Git $Root @('status','--porcelain=v1','-z','--untracked-files=all')}
function Get-StatusRecords([string]$Status){$records=[Collections.Generic.List[object]]::new();$t=@($Status-split[char]0);$i=0;while($i-lt$t.Count){$r=$t[$i++];if([string]::IsNullOrEmpty($r)){continue};if($r.Length-lt 4){throw "Malformed git status record '$r'."};$xy=$r.Substring(0,2);$path=Normalize-Path $r.Substring(3);$other=$null;if($xy -match 'R|C'){if($i-ge$t.Count){throw 'Rename status record is truncated.'};$other=Normalize-Path $t[$i++]};$records.Add([pscustomobject]@{XY=$xy;Path=$path;Other=$other})};return @($records)}
function Filter-Status([string]$Status,[string[]]$Owned,[bool]$WantOwned){$out=[Text.StringBuilder]::new();foreach($r in Get-StatusRecords $Status){$hit=($Owned-ccontains$r.Path)-or($null-ne$r.Other-and$Owned-ccontains$r.Other);if($hit-eq$WantOwned){[void]$out.Append($r.XY).Append('|').Append($r.Path).Append('|').Append($r.Other).Append("`0")}};return $out.ToString()}
function Assert-OwnedNotMixed([string]$Status,[string[]]$Owned){foreach($r in Get-StatusRecords $Status){$hit=($Owned-ccontains$r.Path)-or($null-ne$r.Other-and$Owned-ccontains$r.Other);if($hit-and$r.XY[0]-ne ' '-and$r.XY[0]-ne '?' -and$r.XY[1]-ne ' '-and$r.XY[1]-ne '?'){Stop-Candidate 2 'git.owned-path-mixed-state' "Authorized path '$($r.Path)' has mixed index and worktree state. Stage it with 'git add -- $($r.Path)', or restore it, so its index and worktree agree, then rerun."}}}
function Get-Tree([string]$Root,[string]$Commit){return (Invoke-Git $Root @('rev-parse',"$Commit^{tree}")).Trim()}
function Assert-ExactCommit([string]$Root,[string]$Commit,[string]$Name){if($Commit-cnotmatch'^[0-9a-f]{40}$'-or(Invoke-Git $Root @('rev-parse','--verify',"$Commit^{commit}")).Trim()-cne$Commit){Stop-Candidate 1 'input.commit-invalid' "$Name is not an exact commit identity."}}
function Assert-Candidate([string]$Root,[string]$Commit,[string]$Tree,[string]$Parent){Assert-ExactCommit $Root $Commit 'VerifiedCandidateCommit';if($Tree-cnotmatch'^[0-9a-f]{40}$'-or(Get-Tree $Root $Commit)-cne$Tree){Stop-Candidate 2 'candidate.tree-mismatch' 'Verified candidate tree is not the candidate commit tree.'};$parents=@((Invoke-Git $Root @('show','-s','--format=%P',$Commit)).Trim().Split(' ',[StringSplitOptions]::RemoveEmptyEntries));if($parents.Count-ne 1-or$parents[0]-cne$Parent){Stop-Candidate 2 'candidate.parent-invalid' 'Verified candidate does not have the required sole parent.'}}
function Get-ExactTreeEntry([string]$Root,[string]$Tree,[string]$Path){$lines=@((Invoke-Git $Root @('ls-tree',$Tree,'--',(Get-LiteralPathspec $Path))).Trim().Split("`n",[StringSplitOptions]::RemoveEmptyEntries));if($lines.Count-eq 0){return $null};if($lines.Count-ne 1){Stop-Candidate 2 'input.path-not-single-entry' "Authorized path '$Path' resolves to multiple Git entries."};$m=[regex]::Match($lines[0],"^(?<mode>\d{6})\s+\w+\s+(?<oid>[0-9a-f]{40})\t(?<path>.+)$");if(-not$m.Success-or$m.Groups['path'].Value-cne$Path){Stop-Candidate 2 'input.path-not-single-entry' "Authorized path '$Path' is not one literal Git entry."};return [pscustomobject]@{Mode=$m.Groups['mode'].Value;Oid=$m.Groups['oid'].Value;Path=$Path}}
# Returns true when the path is a landing-set entry this session already committed as a deletion: absent from the expected-tip tree and from disk, but present in the baseline tree. A resumed invocation legitimately carries such a path, so it is a satisfied no-op; a path in neither tree still blocks as a caller typo.
# Both routes drop the returned paths from their 'git add' pathspec list, which git would otherwise reject as matching nothing; a list emptied that way must skip the add entirely, because a bare 'git add -A --' stages the whole worktree.
function Assert-LiteralPathEntry([string]$Root,[string]$Base,[string]$BaselineTree,[string]$Path){$entry=Get-ExactTreeEntry $Root $Base $Path;$disk=Join-Path $Root ($Path.Replace('/','\'));if(Test-Path -LiteralPath $disk -PathType Container){if($null-eq$entry-or$entry.Mode-cne'160000'){Stop-Candidate 1 'input.path-directory' "Authorized path '$Path' is a directory, not one Git entry."}}elseif($null-eq$entry-and-not(Test-Path -LiteralPath $disk -PathType Leaf)){if($null-eq(Get-ExactTreeEntry $Root $BaselineTree $Path)){Stop-Candidate 1 'input.path-not-single-entry' "Authorized path '$Path' is neither an existing file nor a tracked deletion."};return $true};return $false}
function Assert-LiteralPathEntries([string]$Root,[string]$Base,[string]$BaselineTree,[string[]]$Paths){$accepted=[Collections.Generic.List[string]]::new();foreach($path in $Paths){if(Assert-LiteralPathEntry $Root $Base $BaselineTree $path){$accepted.Add($path)}};return $accepted.ToArray()}
function Set-IndexPathFromTree([string]$Root,[string]$Tree,[string]$Path){$entry=Get-ExactTreeEntry $Root $Tree $Path;if($null-eq$entry){Invoke-Git $Root @('update-index','--force-remove','--',$Path)|Out-Null;return};Invoke-Git $Root @('update-index','--add','--cacheinfo',"$($entry.Mode),$($entry.Oid),$Path")|Out-Null}
function Get-IndexPathSnapshot([string]$Root,[string[]]$Paths){$snapshot=[ordered]@{};foreach($path in $Paths){$records=[Collections.Generic.List[object]]::new();foreach($line in @((Invoke-Git $Root @('ls-files','--stage','-z','--',(Get-LiteralPathspec $path)))-split[char]0)){if([string]::IsNullOrEmpty($line)){continue};$m=[regex]::Match($line,"^(?<mode>\d{6})\s+(?<oid>[0-9a-f]{40})\s+(?<stage>[0-3])\t(?<path>.+)$");if(-not$m.Success-or$m.Groups['path'].Value-cne$path){throw "Malformed index entry for '$path'."};$records.Add([pscustomobject]@{Mode=$m.Groups['mode'].Value;Oid=$m.Groups['oid'].Value;Stage=$m.Groups['stage'].Value;Path=$path})};$snapshot[$path]=@($records)};return $snapshot}
function Restore-IndexPathSnapshot([string]$Root,$Snapshot){foreach($path in $Snapshot.Keys){Invoke-Git $Root @('update-index','--force-remove','--',$path)|Out-Null;$entries=@($Snapshot[$path]);if($entries.Count-eq 0){continue};$input=(($entries|ForEach-Object{"$($_.Mode) $($_.Oid) $($_.Stage)`t$($_.Path)"})-join"`n")+"`n";$r=Invoke-NativeInput $Root 'git.exe' (@('-C',$Root,'update-index','--add','--index-info')) $input;if($r.ExitCode-ne 0){throw "Could not restore index entry '$path': $($r.Stderr.Trim())"}}}
function Test-IndexPathSnapshot([string]$Root,$Snapshot){$actual=Get-IndexPathSnapshot $Root @($Snapshot.Keys);foreach($path in $Snapshot.Keys){$expectedText=(@($Snapshot[$path])|ForEach-Object{"$($_.Mode)|$($_.Oid)|$($_.Stage)|$($_.Path)"})-join"`n";$actualText=(@($actual[$path])|ForEach-Object{"$($_.Mode)|$($_.Oid)|$($_.Stage)|$($_.Path)"})-join"`n";if($expectedText-cne$actualText){return $false}};return $true}
function Assert-RouteIdentity([string]$Current,[string]$Primary){$ct=(Invoke-Git $Current @('rev-parse','--show-toplevel')).Trim();$pt=(Invoke-Git $Primary @('rev-parse','--show-toplevel')).Trim();if(-not([IO.Path]::GetFullPath($ct).TrimEnd('\','/').Equals($Current,[StringComparison]::OrdinalIgnoreCase))-or-not([IO.Path]::GetFullPath($pt).TrimEnd('\','/').Equals($Primary,[StringComparison]::OrdinalIgnoreCase))){Stop-Candidate 1 'identity.not-root' 'Current and primary worktrees must be Git roots.'};$cc=(Invoke-Git $Current @('rev-parse','--path-format=absolute','--git-common-dir')).Trim();$pc=(Invoke-Git $Primary @('rev-parse','--path-format=absolute','--git-common-dir')).Trim();if(-not$cc.Equals($pc,[StringComparison]::OrdinalIgnoreCase)){Stop-Candidate 1 'identity.repository-mismatch' 'Current and primary worktrees must share one common Git directory.'};if((Invoke-Git $Current @('branch','--show-current')).Trim()-cne$CurrentBranch-or(Invoke-Git $Primary @('branch','--show-current')).Trim()-cne$PrimaryBranch){Stop-Candidate 2 'identity.branch-mismatch' 'Checked-out branches do not match the requested route.'}}
$historyJsonPath = '.agents/skills/code-quality-metrics/references/history/CodeQualityMetricsHistory.jsonl'
$historySvgPath = '.agents/skills/code-quality-metrics/references/history/CodeQualityMetricsHistory.svg'
$historyPaths = @($historyJsonPath, $historySvgPath)
function Get-BytesSha256([byte[]]$Bytes) { [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($Bytes)).ToLowerInvariant() }
function Get-JsonSha256($Value) { Get-BytesSha256 ([Text.UTF8Encoding]::new($false).GetBytes(($Value | ConvertTo-Json -Compress -Depth 64))) }
function Get-HistoryPatchDigest($Patch) { Get-JsonSha256 ([ordered]@{ changes = $Patch.changes; metricSupportedChanges = $Patch.metricSupportedChanges; cppChanged = $Patch.cppChanged }) }
function Assert-HistoryPathsClean([string]$Root) {
	foreach($path in $historyPaths) {
		$pathspec=Get-LiteralPathspec $path
		$worktree=Invoke-Native $Root 'git.exe' @('-C',$Root,'diff','--quiet','--',$pathspec)
		$index=Invoke-Native $Root 'git.exe' @('-C',$Root,'diff','--cached','--quiet','--',$pathspec)
		$untracked=(Invoke-Git $Root @('ls-files','--others','--exclude-standard','--',$pathspec)).Trim()
		if($worktree.ExitCode-eq 1-or$index.ExitCode-eq 1-or-not[string]::IsNullOrEmpty($untracked)){Stop-Candidate 2 'history.source-dirty' 'Reserved history JSONL/SVG paths must be clean in the real index and worktree before candidate verification or advance.'}
		if($worktree.ExitCode-notin@(0,1)-or$index.ExitCode-notin@(0,1)){Stop-Candidate 1 'history.source-status-failed' 'Git could not verify the reserved history JSONL/SVG paths.'}
	}
}
function Assert-HistoryTreeUnchanged([string]$Root,[string]$Base,[string]$Tip) { $changed=@((Invoke-Git $Root @('diff','--name-only',$Base,$Tip,'--',$historyJsonPath,$historySvgPath))|ForEach-Object{([string]$_).Trim()}|Where-Object{$_});if($changed.Count-ne 0){Stop-Candidate 2 'history.source-changed' 'The candidate source patch changes generator-owned history JSONL/SVG paths.'} }
function Get-CommitMetadata([string]$Root,[string]$Commit) { [ordered]@{ message = Invoke-Git $Root @('show','--no-show-signature','-s','--format=%B',$Commit); authorName=(Invoke-Git $Root @('show','--no-show-signature','-s','--format=%an',$Commit)).Trim(); authorEmail=(Invoke-Git $Root @('show','--no-show-signature','-s','--format=%ae',$Commit)).Trim(); authorDate=(Invoke-Git $Root @('show','--no-show-signature','-s','--format=%aI',$Commit)).Trim(); committerName=(Invoke-Git $Root @('show','--no-show-signature','-s','--format=%cn',$Commit)).Trim(); committerEmail=(Invoke-Git $Root @('show','--no-show-signature','-s','--format=%ce',$Commit)).Trim(); committerDate=(Invoke-Git $Root @('show','--no-show-signature','-s','--format=%cI',$Commit)).Trim() } }
function Get-HistoryContract([string]$Root,[string]$Base,[string]$Tip) { if($FixtureFailure-eq'history-contract'){Stop-Candidate 2 'history.contract-failed' 'Fixture forced history Contract failure.'};$receipt=Invoke-HistoryModeJsonRaw $Root 'Contract' $Base $Tip $null $null;$runtime=if($receipt.capture){[string]$receipt.capture.bootstrapIdentityDigest}else{$null};return [ordered]@{receipt=$receipt;digest=Get-JsonSha256 $receipt;generatorDigest=[string]$receipt.generator.sha256;captureDigest=$(if($receipt.capture){[string]$receipt.capture.digest}else{$null});runtimeDigest=$runtime;patchDigest=Get-HistoryPatchDigest $receipt.patch;mode=[string]$receipt.decision.captureMode} }
function Assert-PrimaryLandingLock([string]$Root,[string]$Common) { if([string]::IsNullOrWhiteSpace($OwnerToken)-or$OwnerToken-cnotmatch'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'){Stop-Candidate 1 'landing-lock.owner-required' 'AdvancePrimary requires the caller-owned landing lock token.'};if([string]::IsNullOrWhiteSpace($SessionLabel)){Stop-Candidate 1 'landing-lock.session-required' 'AdvancePrimary requires the caller landing session label.'};$cli=$WorktreeCliExecutable;if(-not$cli){$cli=Join-Path $Root 'Tools\WorktreeCli\Platforms\VisualStudio2026\Output\WorktreeCli.exe'};$cliItem=Get-Item -LiteralPath $cli -Force -ErrorAction SilentlyContinue;if($null-eq$cliItem-or$cliItem.PSIsContainer-or($cliItem.Attributes-band[IO.FileAttributes]::ReparsePoint)-or([long]$cliItem.Length -le 0)){Stop-Candidate 1 'landing-lock.executable-missing' 'AdvancePrimary could not locate an ordinary WorktreeCli.exe.'};$response=Invoke-Native $Root $cliItem.FullName @('lock','status','--repo',$Common);if($response.ExitCode-ne 0){Stop-Candidate 2 'landing-lock.status-failed' 'Could not read the caller-owned landing lock.'};try{$status=$response.Stdout|ConvertFrom-Json -Depth 32 -ErrorAction Stop}catch{Stop-Candidate 2 'landing-lock.status-invalid' 'WorktreeCli returned invalid landing-lock JSON.'};$properties=@($status.PSObject.Properties.Name);if(-not($properties-ccontains'held')-or$status.held-isnot[bool]-or-not$status.held-or-not($properties-ccontains'leaseState')-or$status.leaseState-cne'live'-or-not($properties-ccontains'owner')-or$status.owner-cne$OwnerToken-or-not($properties-ccontains'session')-or$status.session-cne$SessionLabel-or-not($properties-ccontains'worktree')-or-not([IO.Path]::GetFullPath([string]$status.worktree).TrimEnd('\','/').Equals($Root,[StringComparison]::OrdinalIgnoreCase))){Stop-Candidate 2 'landing-lock.not-owned' 'AdvancePrimary requires a live lock owned by OwnerToken for the requested session and primary worktree.'};if(-not($properties-ccontains'leaseDurationSeconds')-or$status.leaseDurationSeconds-isnot[int] -and $status.leaseDurationSeconds-isnot[int64] -and $status.leaseDurationSeconds-isnot[long] -or[int64]$status.leaseDurationSeconds-lt 3600){Stop-Candidate 2 'landing-lock.duration-too-short' 'AdvancePrimary requires the caller-owned 3600-second landing lease.'};return $cliItem.FullName }
function Get-FileSnapshot([string]$Root,[string[]]$Paths){$snapshot=[ordered]@{};foreach($path in $Paths){$full=Join-Path $Root ($path.Replace('/','\'));$item=Get-Item -LiteralPath $full -Force -ErrorAction SilentlyContinue;$snapshot[$path]=[ordered]@{exists=($null-ne$item-and$item.PSIsContainer-ne$true);bytes=$(if($null-ne$item-and-not$item.PSIsContainer){[IO.File]::ReadAllBytes($full)}else{@()})}};return $snapshot }
function Restore-FileSnapshot([string]$Root,$Snapshot){foreach($path in $Snapshot.Keys){$full=Join-Path $Root ($path.Replace('/','\'));$state=$Snapshot[$path];if($state.exists){$parent=Split-Path -Parent $full;if(-not(Test-Path -LiteralPath $parent)){New-Item -ItemType Directory -Force $parent|Out-Null};[IO.File]::WriteAllBytes($full,[byte[]]$state.bytes)}elseif(Test-Path -LiteralPath $full){Remove-Item -LiteralPath $full -Force}}}
function New-HistoryReplacement([string]$Root,[string]$SourceCommit,[string]$Parent,$Artifacts,$Metadata,[string]$TempRoot) { $indexPath=Join-Path $TempRoot ('overlay-'+[guid]::NewGuid().ToString('N')+'.index');$oldIndex=$env:GIT_INDEX_FILE;$messagePath=Join-Path $TempRoot ('message-'+[guid]::NewGuid().ToString('N')+'.txt');try{$env:GIT_INDEX_FILE=$indexPath;Invoke-Git $Root @('read-tree',$SourceCommit)|Out-Null;$jsonBlob=(Invoke-Git $Root @('hash-object','-w','--path',$historyJsonPath,$Artifacts.JsonPath)).Trim();$svgBlob=(Invoke-Git $Root @('hash-object','-w','--path',$historySvgPath,$Artifacts.SvgPath)).Trim();Invoke-Git $Root @('update-index','--add','--cacheinfo',"100644,$jsonBlob,$historyJsonPath")|Out-Null;Invoke-Git $Root @('update-index','--add','--cacheinfo',"100644,$svgBlob,$historySvgPath")|Out-Null;$tree=(Invoke-Git $Root @('write-tree')).Trim();[IO.File]::WriteAllText($messagePath,([string]$Metadata.message).TrimEnd("`r","`n")+"`n",[Text.UTF8Encoding]::new($false));$commitEnv=@{GIT_AUTHOR_NAME=$Metadata.authorName;GIT_AUTHOR_EMAIL=$Metadata.authorEmail;GIT_AUTHOR_DATE=$Metadata.authorDate;GIT_COMMITTER_NAME=$Metadata.committerName;GIT_COMMITTER_EMAIL=$Metadata.committerEmail;GIT_COMMITTER_DATE=$Metadata.committerDate};$commit=(Invoke-Native $Root 'git.exe' @('-C',$Root,'commit-tree',$tree,'-p',$Parent,'-F',$messagePath) $commitEnv);if($commit.ExitCode-ne 0-or$commit.Stdout.Trim()-cnotmatch'^[0-9a-f]{40}$'){Stop-Candidate 1 'git.commit-tree-failed' "History replacement commit failed: $($commit.Stderr.Trim())"};return [pscustomobject]@{Commit=$commit.Stdout.Trim();Tree=$tree;Parent=$Parent}}finally{if($null-eq$oldIndex){Remove-Item Env:GIT_INDEX_FILE -ErrorAction SilentlyContinue}else{$env:GIT_INDEX_FILE=$oldIndex};Remove-Item -LiteralPath $indexPath,$messagePath -Force -ErrorAction SilentlyContinue}}
function Invoke-PrimaryHistoryAdvance([string]$Root,[string]$Common,[string]$SourceCommit,[string]$SourceTree,[string]$Parent,[string[]]$SourcePaths,[string]$BeforeStatus) {
	$cli=Assert-PrimaryLandingLock $Root $Common;Assert-HistoryPathsClean $Root;Assert-HistoryTreeUnchanged $Root $Parent $SourceCommit
	$contract=Get-HistoryContract $Root $Parent $SourceCommit;$result.historyContract=[ordered]@{schemaVersion='broken-engine-code-quality-history-contract/v1';status='pass';receipt=$contract.receipt;contractDigest=$contract.digest;generatorDigest=$contract.generatorDigest;captureDigest=$contract.captureDigest;runtimeDigest=$contract.runtimeDigest;patchDigest=$contract.patchDigest;mode=$contract.mode}
	if($HistoryContractGeneratorDigest-and$contract.generatorDigest-ne$HistoryContractGeneratorDigest){Stop-Candidate 2 'history.contract-changed' 'History generator identity changed after verification.'}
	$approvedMode=$HistoryContractMode;$currentMode=$contract.mode;$modeAllowed=$currentMode-eq$approvedMode;if(-not$modeAllowed){Stop-Candidate 2 'history.contract-changed' "History capture mode changed from '$approvedMode' to '$currentMode'."};if($currentMode-in@('catch-up','cpp-change')-and[string]::IsNullOrWhiteSpace($contract.captureDigest)){Stop-Candidate 2 'history.contract-changed' 'Active history capture identity is missing.'};if($HistoryContractCaptureDigest-and$contract.captureDigest-ne$HistoryContractCaptureDigest){Stop-Candidate 2 'history.contract-changed' 'History capture identity changed after verification.'};if($HistoryContractRuntimeDigest-and$contract.runtimeDigest-ne$HistoryContractRuntimeDigest){Stop-Candidate 2 'history.contract-changed' 'History runtime identity changed after verification.'};if($HistoryContractPatchDigest-and$contract.patchDigest-ne$HistoryContractPatchDigest){Stop-Candidate 2 'history.source-changed' 'History Contract patch classification changed after verification.'};if($contract.digest-cne$HistoryContractDigest){Stop-Candidate 2 'history.contract-changed' 'History Contract aggregate digest changed after verification.'}
